import sys

def is_palindrome(n):
    s = str(n)
    return s == s[::-1]

def max_palindromic_cube(N):
    low = 1
    high = int(N ** (1/3)) + 1

    while low < high:
        mid = (low + high + 1) // 2
        cube = mid ** 3

        if cube > N:
            high = mid - 1
        else:
            if is_palindrome(cube):
                low = mid
            else:
                high = mid - 1

    return low ** 3

