import sys

def is_airport_code(S, T):
    # Check if T has exactly 3 characters
    if len(T) == 3:
        # Check if T can be formed by converting a subsequence of length 3 from S
        for i in range(len(S) - 2):
            if S[i:i+3].upper() == T:
                return "Yes"

    # Check if T has exactly 2 characters
    elif len(T) == 2:
        # Check if T can be formed by converting a subsequence of length 2 from S and appending 'X'
        for i in range(len(S) - 1):
            if S[i:i+2].upper() + 'X' == T:
                return "Yes"

    # If neither condition is met, T is not an airport code
    return "No"

# Read input
S = sys.stdin.readline().strip()
T = sys.stdin.readline().strip()

# Output the result
print(is_airport_code(S, T))
