```python
import sys

def find_final_element(N, A):
    # Initialize the list to store the input values
    elements = [0] * (N + 1)

    # Fill the list with the input values
    for i in range(1, N + 1):
        elements[i] = A[i - 1]

    # Iterate through the elements and combine them based on their indices
    for i in range(1, N):
        for j in range(i + 1, N + 1):
            if elements[i] >= elements[j]:
                elements[j] = elements[i]
            else:
                elements[i] = elements[j]

    # The final element is the smallest element in the list
    return min(elements)

# Read input from standard input
N = int(input())
A = list(map(int, input().split()))

# Find and print the final element
print(find_final_element(N, A))
