```python
import sys
from itertools import permutations

def dfs(graph, visited, path, target):
    if len(path) == len(graph):
        return path == target
    for neighbor in graph[path[-1]]:
        if not visited[neighbor]:
            visited[neighbor] = True
            if dfs(graph, visited, path + [neighbor], target):
                return True
            visited[neighbor] = False
    return False

def is_isomorphic(G, H, A):
    N = len(G)
    M_H = len(H)

    # Create adjacency lists for G and H
    adj_G = [[] for _ in range(N)]
    adj_H = [[] for _ in range(N)]

    for u, v in G:
        adj_G[u - 1].append(v - 1)
        adj_G[v - 1].append(u - 1)

    for u, v in H:
        adj_H[u - 1].append(v - 1)
        adj_H[v - 1].append(u - 1)

    # Check all permutations of H's vertices
    for perm in permutations(range(1, N + 1)):
        visited = [False] * N
        if dfs(adj_H, visited, [perm[0] - 1], perm):
            # Calculate the cost of transforming H to G using the given A matrix
            cost = 0
            for i in range(M_H):
                u, v = H[i]
                if (u - 1, v - 1) not in adj_H[perm[u - 1] - 1] and (v - 1, u - 1) not in adj_H[perm[v - 1] - 1]:
                    cost += A[u - 1][v - 1]
                elif (u - 1, v - 1) in adj_H[perm[u - 1] - 1] and (v - 1, u - 1) in adj_H[perm[v - 1] - 1]:
                    cost -= A[u - 1][v - 1]
            return cost

    return float('inf')

# Read input
N = int(input())
G = []
for _ in range(int(input())):
    u, v = map(int, input().split())
    G.append((u, v))
H = []
for _ in range(int(input())):
    u, v = map(int, input().split())
    H.append((u, v))
A = []
for _ in range(N):
    A.append(list(map(int, input().split())))

# Find the minimum cost to make G and H isomorphic
result = is_isomorphic(G, H, A)
print(result)
```

