```python
import heapq

def max_humidified_cells(H, W, D):
    grid = [list(input().strip()) for _ in range(H)]
    covered = set()

    # Priority queue to store cells based on their Manhattan distance from the current position
    pq = []

    # Add all floor cells to the priority queue
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                heapq.heappush(pq, (0, i, j))

    # Place humidifiers
    while pq:
        dist, x, y = heapq.heappop(pq)

        # If the cell is already covered, skip it
        if (x, y) in covered:
            continue

        # Mark the cell as covered
        covered.add((x, y))

        # Add all adjacent cells to the priority queue
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.':
                heapq.heappush(pq, (dist + 1, nx, ny))

    return len(covered)

# Read input
H, W, D = map(int, input().split())
print(max_humidified_cells(H, W, D))
