        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def count_numbers_with_9_divisors(N):
    count = 0
    max_prime = int(N**0.5)
    for p in range(2, max_prime + 1):
        if is_prime(p):
            power = 1
            while p**(power + 1) <= N:
                power += 1
            if power == 8:
                count += 1
    return count

if __name__ == "__main__":
    N = int(sys.stdin.readline().strip())
    print(count_numbers_with_9_divisors(N))
