import sys
from typing import List

class SegmentTree:
    def __init__(self, n: int):
        self.n = n
        self.tree = [0] * (4 * n)
        self.lazy = [0] * (4 * n)

    def push(self, node: int, start: int, end: int) -> None:
        if self.lazy[node]:
            self.tree[node] += self.lazy[node] * (end - start + 1)
            if start != end:
                self.lazy[2 * node] += self.lazy[node]
                self.lazy[2 * node + 1] += self.lazy[node]
            self.lazy[node] = 0

    def update(self, node: int, start: int, end: int, l: int, r: int, val: int) -> None:
        self.push(node, start, end)
        if l > end or r < start:
            return
        if l <= start and end <= r:
            self.tree[node] += val * (end - start + 1)
            if start != end:
                self.lazy[2 * node] += val
                self.lazy[2 * node + 1] += val
            return
        mid = (start + end) // 2
        self.update(2 * node, start, mid, l, r, val)
        self.update(2 * node + 1, mid + 1, end, l, r, val)
        self.tree[node] = self.tree[2 * node] + self.tree[2 * node + 1]

    def query(self, node: int, start: int, end: int, l: int, r: int) -> int:
        self.push(node, start, end)
        if l > end or r < start:
            return 0
        if l <= start and end <= r:
            return self.tree[node]
        mid = (start + end) // 2
        return self.query(2 * node, start, mid, l, r) + self.query(2 * node + 1, mid + 1, end, l, r)

def solve():
    N = int(input())
    contests = []
    for _ in range(N):
        L, R = map(int, input().split())
        contests.append((L, R))

    Q = int(input())
    queries = list(map(int, input().split()))

    segment_tree = SegmentTree(500001)
    result = []

    for query in queries:
        total_change = 0
        for L, R in contests:
            if L <= query <= R:
                total_change += 1
        segment_tree.update(1, 1, 500000, query, query, total_change)
        result.append(segment_tree.query(1, 1, 500000, query, query))

    print('\n'.join(map(str, result)))

if __name__ == "__main__":
    solve()
