import sys
from typing import List

def build_segment_tree(arr: List[int], tree: List[int], start: int, end: int, node: int) -> None:
    if start == end:
        tree[node] = arr[start]
        return
    mid = (start + end) // 2
    build_segment_tree(arr, tree, start, mid, 2 * node)
    build_segment_tree(arr, tree, mid + 1, end, 2 * node + 1)
    tree[node] = max(tree[2 * node], tree[2 * node + 1])

def update_segment_tree(arr: List[int], tree: List[int], start: int, end: int, node: int, idx: int, val: int) -> None:
    if start == end:
        arr[idx] = val
        tree[node] = val
        return
    mid = (start + end) // 2
    if idx <= mid:
        update_segment_tree(arr, tree, start, mid, 2 * node, idx, val)
    else:
        update_segment_tree(arr, tree, mid + 1, end, 2 * node + 1, idx, val)
    tree[node] = max(tree[2 * node], tree[2 * node + 1])

def query_segment_tree(tree: List[int], start: int, end: int, node: int, left: int, right: int) -> int:
    if left > end or right < start:
        return 0
    if left <= start and end <= right:
        return tree[node]
    mid = (start + end) // 2
    return max(query_segment_tree(tree, start, mid, 2 * node, left, right),
               query_segment_tree(tree, mid + 1, end, 2 * node + 1, left, right))

def main():
    input = sys.stdin.read
    data = list(map(int, input().split()))
    N, Q = data[0], data[1]
    arr = data[2:N+2]
    tree = [0] * (4 * N)
