```python
import sys

def solve():
    N, M = map(int, input().split())

    # If M is 0, check if N is 0
    if M == 0:
        if N == 0:
            print(0)
        else:
            print(-1)
        return

    # If N is 0, return 0
    if N == 0:
        print(0)
        return

    # If M is 1, check if X_1 = Y_1 and Z_1 = 0
    if M == 1:
        X, Y, Z = map(int, input().split())
        if X != Y or Z != 0:
            print(-1)
        else:
            print(0, 0)
        return

    # Initialize the sequence A and the frequency dictionary
    A = [0] * N
    freq = {}

    # Iterate through the constraints
    for _ in range(M):
        X, Y, Z = map(int, input().split())

        # Calculate the XOR of A[X-1] and A[Y-1]
        xor_value = A[X-1] ^ A[Y-1]

        # Decide which element to set based on the XOR value and Z
        if xor_value == Z:
            continue
        elif xor_value < Z:
            # Set A[X-1] to make the XOR equal to Z
            A[X-1] ^= Z
        else:
            # Set A[Y-1] to make the XOR equal to Z
            A[Y-1] ^= Z

        # Update the frequency dictionary
        if A[X-1] in freq:
            freq[A[X-1]] += 1
        else:
            freq[A[X-1]] = 1

        if A[Y-1] in freq:
            freq[A[Y-1]] += 1
        else:
            freq[A[Y-1]] = 1

    # Check if the sequence is valid
    for i in range(M):
        X, Y, Z = map(int, input().split())
        if A[X-1] ^ A[Y-1] != Z:
            print(-1)
            return

    # Find the minimum sum of the sequence
    min_sum = float('inf')
    best_sequence = None
    for i in range(N):
        if freq[i+1] > 0:
            current_sum = sum(A)
            if current_sum < min_sum:
                min_sum = current_sum
                best_sequence = A[:]

    # Print the best sequence
    if best_sequence is not None:
        print(*best_sequence)
    else:
        print(-1)

solve()
