from collections import deque

def main():
    N, R, C = map(int, input().split())
    S = input()

    # Initialize the queue with the starting position of smoke
    queue = deque([(0, 0)])

    # Process each time step
    for t in range(1, N + 1):
        # Move smoke based on the direction at time t
        if S[t - 1] == 'N':
            queue.append((queue[0][0] - 1, queue[0][1]))
        elif S[t - 1] == 'W':
            queue.append((queue[0][0], queue[0][1] - 1))
        elif S[t - 1] == 'S':
            queue.append((queue[0][0] + 1, queue[0][1]))
        elif S[t - 1] == 'E':
            queue.append((queue[0][0], queue[0][1] + 1))

        # Remove the position of smoke that has moved to its new position
        queue.popleft()

    # Check if the position (R, C) is in the queue at time t + 0.5
    result = []
    for t in range(1, N + 1):
        if (R, C) in queue:
            result.append('1')
        else:
            result.append('0')

    # Print the result
    print(''.join(result))

if __name__ == "__main__":
