    visited[node] = True
    for neighbor in graph[node]:
        if not visited[neighbor]:
            if dfs(neighbor, node, visited):
                return True
        elif neighbor != parent:
            return True
    return False

def min_edges_to_delete(n, m):
    graph = defaultdict(list)
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    cycle_count = 0

    for node in range(1, n + 1):
        if not visited[node]:
            if dfs(node, -1, visited):
                cycle_count += 1

    return cycle_count

