import sys
from collections import defaultdict

def is_400_number(n):
    # Initialize a dictionary to count occurrences of each prime factor
    prime_counts = defaultdict(int)

    # Check for smallest prime factor 2
    while n % 2 == 0:
        prime_counts[2] += 1
        n //= 2

    # Check for odd factors from 3 onwards
    factor = 3
    while factor * factor <= n:
        while n % factor == 0:
            prime_counts[factor] += 1
            n //= factor
        factor += 2

    # If n is still greater than 2, then it is a prime number
    if n > 2:
        prime_counts[n] += 1

    # Check if there are exactly 2 distinct prime factors
    if len(prime_counts) != 2:
        return False

    # Check if each prime factor divides the number an even number of times
    for count in prime_counts.values():
        if count % 2 != 0:
            return False

    return True

def solve_queries(queries):
    results = []
    for query in queries:
        max_400_number = query
        while not is_400_number(max_400_number):
            max_400_number -= 1
        results.append(max_400_number)
    return results

if __name__ == "__main__":
    Q = int(input())
    queries = [int(input()) for _ in range(Q)]
    results = solve_queries(queries)
    for result in results:
        print(result)
