import sys
from collections import defaultdict

# Read input
input = sys.stdin.read
data = input().split()
Q = int(data[0])
queries = [int(data[i]) for i in range(1, Q + 1)]

# Precompute prime numbers up to 10^6
def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (is_prime[p] == True):
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = []
    for p in range(2, limit + 1):
        if is_prime[p]:
            prime_numbers.append(p)
    return prime_numbers

primes = sieve_of_eratosthenes(10**6)

# Function to check if a number is a 400 number
def is_400_number(n):
    prime_factors = set()
    for prime in primes:
        if prime > n:
            break
        if n % prime == 0:
            prime_factors.add(prime)
            while n % prime == 0:
                n //= prime
    # Check if there are exactly 2 distinct prime factors
    if len(prime_factors) != 2:
        return False
    # Check if each prime factor divides the number an even number of times
    for prime in prime_factors:
        count = 0
        while n % prime == 0:
            n //= prime
            count += 1
        if count % 2 != 0:
            return False
    return True

# Process each query
for query in queries:
    largest_400_number = 0
    for i in range(query, 0, -1):
        if is_400_number(i):
            largest_400_number = i
            break
    print(largest_400_number)
