import sys
from collections import defaultdict

def find(x):
    if parent[x] != x:
        parent[x] = find(parent[x])
    return parent[x]

def union(x, y):
    rootX = find(x)
    rootY = find(y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1

def main():
    input = sys.stdin.read
    data = list(map(int, input().split()))
    N, M = data[0], data[1]
    B = data[2:]

    # Initialize Union-Find data structures
    parent = list(range(N))
    rank = [0] * N

    # Count the number of connected components
    def count_connected_components():
        count = 0
        for i in range(N):
            if parent[i] == i:
                count += 1
        return count

    # Calculate the sum of f(B') for all possible B'
    total_sum = 0
    for i in range(N):
        if B[i] == -1:
            # Replace B[i] with each integer from 1 to M
            for j in range(1, M + 1):
                B[i] = j
                # Build the graph
                for k in range(i + 1, N):
                    if B[k] >= B[i]:
