def find_pair(N):
    if N == 1:
        return (2, 3)

    # Initialize the order dictionary
    order = defaultdict(int)
    current = 1
    M = 2

    while True:
        if current == 1:
            break
        if order[current] > 0:
            return (current, M)
        order[current] = len(order)
        current = (current * 2) % M
        M += 1

