import sys

def count_valid_sequences(n, s):
    MOD = 998244353

    # Function to check if a string is a valid parenthesis sequence
    def is_valid(seq):
        stack = []
        for char in seq:
            if char == '(':
                stack.append(char)
            elif char == ')' and stack:
                stack.pop()
            else:
                return False
        return not stack

    # Function to reverse a substring and check if the result is valid
    def reverse_and_check(l, r):
        reversed_seq = s[l:r+1][::-1]
        return is_valid(reversed_seq)

    # Initialize the count of valid sequences
    count = 1

    # Iterate over all possible substrings
    for i in range(n):
        for j in range(i, n):
            if is_valid(s[i:j+1]):
                # Check if reversing the substring results in a valid sequence
                if reverse_and_check(i, j):
                    count += 1
                    count %= MOD

    return count

