import sys
from math import factorial
from itertools import permutations

sys.setrecursionlimit(10**6)

def find(x, parent):
    if parent[x] != x:
        parent[x] = find(parent[x], parent)
    return parent[x]

def union(x, y, parent, rank):
    root_x = find(x, parent)
    root_y = find(y, parent)
    if root_x == root_y:
        return
    if rank[root_x] > rank[root_y]:
        parent[root_y] = root_x
    elif rank[root_x] < rank[root_y]:
        parent[root_x] = root_y
    else:
        parent[root_y] = root_x
        rank[root_x] += 1

def dfs(node, parent, depth, dist, visited):
    visited[node] = True
    for child in range(2, N + 1):
        if parent[child] == node and not visited[child]:
            dist[child] = depth + A[child - 2]
            dfs(child, parent, depth + 1, dist, visited)

def calculate_distances(parent, A):
    visited = [False] * (N + 1)
    dist = [0] * (N + 1)
    dfs(1, parent, 0, dist, visited)
    return dist

def main():
    N, Q = map(int, input().split())
    A = list(map(int, input().split()))
    queries = []
    for _ in range(Q):
        u, v = map(int, input().split())
        queries.append((u, v))

    mod = 998244353
    result = []

    for u, v in queries:
        parent = list(range(N + 1))
        rank = [0] * (N + 1)
        for i in range(2, N + 1):
            parent[i] = i
            rank[i] = 1

        for perm in permutations(range(2, N + 1)):
            for i in range(1, N):
                if perm[i] != perm[i + 1]:
                    union(perm[i], perm[i + 1], parent, rank)

            if find(u, parent) == find(v, parent):
                dist = calculate_distances(parent, A)
                result.append(sum(dist) % mod)

    for r in result:
        print(r)

if __name__ == "__main__":
    main()
```

