MOD = 998244353

def dfs(i, j, visited, dp):
    if (i, j) in dp:
        return dp[(i, j)]

    if i > j:
        return 1

    if S[i] == 'W' and S[j] == 'B':
        dp[(i, j)] = (dfs(i + 1, j - 1, visited, dp) * (j - i)) % MOD
    elif S[i] == 'B' and S[j] == 'W':
        dp[(i, j)] = (dfs(i + 1, j - 1, visited, dp) * (j - i)) % MOD
    else:
        dp[(i, j)] = (dfs(i + 1, j, visited, dp) + dfs(i, j - 1, visited, dp)) % MOD

    return dp[(i, j)]

def count_partitions(N):
    if N % 2 != 0:
        return 0

    S = input().strip()
    dp = {}
    return dfs(0, N - 1, set(), dp)

